const j = $json;
const SELF = 'kqualitycleaningservices@gmail.com';
const EMAIL_RE = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/;
function normId(s) { return s ? String(s).trim().replace(/^<|>$/g, '') : ''; }
function getHeader(name) {
  const h = j.headers;
  if (!h) return undefined;
  if (typeof h.get === 'function') return h.get(name);
  if (Array.isArray(h)) { const f = h.find(x => Array.isArray(x) && String(x[0]).toLowerCase() === name); return f ? f[1] : undefined; }
  if (typeof h === 'object') { const k = Object.keys(h).find(k => k.toLowerCase() === name); return k ? h[k] : undefined; }
  return undefined;
}
function headerVal(name) {
  const v = getHeader(name);
  if (v === undefined || v === null) return '';
  if (typeof v === 'object') return '';
  return String(v).replace(new RegExp('^' + name + '\\s*:\\s*', 'i'), '').trim();
}
function emailOf(x) {
  if (!x) return '';
  if (typeof x === 'string') { const m = x.match(EMAIL_RE); return m ? m[0] : ''; }
  if (x.value && x.value[0] && x.value[0].address) return String(x.value[0].address);
  if (x.text) { const m = String(x.text).match(EMAIL_RE); return m ? m[0] : ''; }
  return '';
}
function hash64(s) {
  let h1 = 0x811c9dc5, h2 = 0x01000193;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    h1 = Math.imul(h1 ^ c, 0x01000193) >>> 0;
    h2 = Math.imul(h2 ^ c, 0x85ebca6b) >>> 0;
  }
  return h1.toString(36) + h2.toString(36);
}
const rawMessageId = j.messageId || headerVal('message-id');
const rawInReplyTo = j.inReplyTo || headerVal('in-reply-to');
const rawReferences = j.references || headerVal('references') || '';
let referencesArr = [];
if (Array.isArray(rawReferences)) referencesArr = rawReferences.map(normId);
else if (typeof rawReferences === 'string' && rawReferences) referencesArr = rawReferences.split(/\s+/).map(normId);
if (rawInReplyTo) referencesArr.push(normId(rawInReplyTo));
referencesArr = [...new Set(referencesArr.filter(Boolean))];
const subject = String(j.subject || headerVal('subject') || '').slice(0, 300);
const fromEmail = (emailOf(j.from) || emailOf(headerVal('from'))).toLowerCase().trim();
const bodyText = String(j.text || j.textPlain || '').slice(0, 8000);
const receivedAt = j.date ? new Date(j.date).toISOString() : new Date().toISOString();
const seed = receivedAt + '|' + fromEmail + '|' + subject + '|' + bodyText.slice(0, 2000);
const messageId = normId(rawMessageId) || ('generated-' + receivedAt + '-' + hash64(seed));
const baseSubject = subject.replace(/^((RE|FW|FWD)\s*:\s*)+/i, '').trim();
const isSelf = !!fromEmail && fromEmail === SELF;
return { json: { message_id: messageId, in_reply_to: normId(rawInReplyTo), references: referencesArr, from_email: fromEmail, subject, base_subject: baseSubject, is_self: isSelf, body_text: bodyText, received_at: receivedAt } };

