const res = $json;
const ok = res && res.success === true && res.data && res.data.note;
const stamp = new Date().toISOString().slice(0, 10);
const note = ok
  ? ('[AI ' + stamp + '] ' + res.data.note + (res.data.next_action ? (' Next action: ' + res.data.next_action) : '') + ' (sentiment: ' + (res.data.sentiment || 'n/a') + ')')
  : ('[' + stamp + '] Reply received: "' + (n.subject || '') + '"');
const ai_line = ok
  ? ('AI summary: ' + res.data.note + '\nSentiment: ' + (res.data.sentiment || 'n/a') + (res.data.next_action ? ('\nSuggested next action: ' + res.data.next_action) : ''))
  : '';
return { json: { candidate_id: m.candidate_id, note, ai_line, business_name: m.business_name, candidate_email: m.candidate_email, method: ok ? ('ai_crm_note_' + res.prompt_version) : 'fallback' } };
